pub fn all_characters_same(s: &[u8]) -> bool {
    // Empty and single-element slices are trivially "all identical".
    let Some((&first, rest)) = s.split_first() else {
        return true;
    };

    // All characters are the same iff every element equals the first.
    rest.iter().all(|&b| b == first)
}

